args.content:
`timescale 1ns / 1ps

// Temporary verification testbench for lab3 (not part of the repo).
// Runs the preloaded sort program, prints UART characters, and at the end
// dumps the sorted arrays from data RAM plus a few WB-stage write-backs.
module tb_lab3;
    reg clk, rst;
    wire [7:0] uart_char;
    wire uart_valid;
    wire [31:0] wb_pc, wb_inst;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(wb_pc),
        .wb_inst(wb_inst),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0),
        .sim_uart_char_out(uart_char),
        .sim_uart_char_valid(uart_valid)
    );

    integer cycle = 0;
    integer halt_count = 0;
    integer i;

    initial begin
        clk = 0;
        rst = 1;
        #10 rst = 0;
    end
    always #5 clk = ~clk;

    always @(posedge clk) begin
        if (!rst) begin
            if (uart_valid) $write("%c", uart_char);
            cycle = cycle + 1;
            // halt: jal zero,halt (0x204) on check failure,
            //       jal zero,_trm_init+0x14 (0x21c) after main returns
            if (wb_pc == 32'h204 || wb_pc == 32'h21c)
                halt_count = halt_count + 1;
            else
                halt_count = 0;
            if (halt_count > 40) begin
                $display("\n[TB] program reached terminal loop at wb_pc=%h after %0d cycles", wb_pc, cycle);
                dump_ram;
                $finish;
            end
            if (cycle > 2000000) begin
                $display("\n[TB] TIMEOUT after %0d cycles", cycle);
                dump_ram;
                $finish;
            end
        end
    end

    task dump_ram;
        begin
            $display("[TB] a[] sorted (expect 0..19):");
            for (i = 0; i < 20; i = i + 1)
                $write("%0d ", {core.data_ram.data[32'h17 + 4*i],
                                core.data_ram.data[32'h16 + 4*i],
                                core.data_ram.data[32'h15 + 4*i],
                                core.data_ram.data[32'h14 + 4*i]});
            $display("");
            $display("[TB] b[] sorted (expect 19..0):");
            for (i = 0; i < 20; i = i + 1)
                $write("%0d ", {core.data_ram.data[32'h67 + 4*i],
                                core.data_ram.data[32'h66 + 4*i],
                                core.data_ram.data[32'h65 + 4*i],
                                core.data_ram.data[32'h64 + 4*i]});
            $display("");
        end
    endtask

endmodule
